const cartState = {
    items: [],
    count: 0
};

// Mobile menu toggle
const menuToggle = document.querySelector('.menu-toggle');
const navMenu = document.querySelector('#nav-menu');

menuToggle.addEventListener('click', () => {
    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
    menuToggle.setAttribute('aria-expanded', !isExpanded);
    navMenu.classList.toggle('active');
});

// Close menu when clicking on a nav link
const navLinks = document.querySelectorAll('.nav-link');
navLinks.forEach(link => {
    link.addEventListener('click', () => {
        menuToggle.setAttribute('aria-expanded', 'false');
        navMenu.classList.remove('active');
    });
});

// Add to cart functionality
const addToCartButtons = document.querySelectorAll('.add-to-cart-btn');
const cartCount = document.querySelector('.cart-count');

addToCartButtons.forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();

        const productCard = button.closest('.product-card');
        const productName = productCard.querySelector('h3').textContent;
        const price = productCard.querySelector('.price').textContent;

        // Add item to cart
        cartState.items.push({
            name: productName,
            price: price
        });
        cartState.count++;

        // Update cart UI
        updateCart();

        // Show feedback
        showCartFeedback(button);
    });
});

function updateCart() {
    cartCount.textContent = cartState.count;
    cartCount.setAttribute('aria-label', `${cartState.count} items in cart`);
}

function showCartFeedback(button) {
    const originalText = button.textContent;
    button.textContent = 'Added!';
    button.disabled = true;

    setTimeout(() => {
        button.textContent = originalText;
        button.disabled = false;
    }, 1500);
}

// Deal buttons
const dealButtons = document.querySelectorAll('.deal-btn');
dealButtons.forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();
        const dealCard = button.closest('.deal-card');
        const dealTitle = dealCard.querySelector('h3').textContent;

        // Announce to screen readers
        announceAction(`Viewing ${dealTitle} collection`);
    });
});

// Newsletter form
const newsletterForm = document.querySelector('.newsletter-form');
const emailInput = document.querySelector('#email');

if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const email = emailInput.value;

        // Basic email validation
        if (!isValidEmail(email)) {
            showValidationError('Please enter a valid email address');
            return;
        }

        // Simulate submission
        const button = newsletterForm.querySelector('button');
        const originalText = button.textContent;
        button.disabled = true;
        button.textContent = 'Subscribing...';

        setTimeout(() => {
            button.textContent = 'Subscribed!';
            emailInput.value = '';
            announceAction('Successfully subscribed to our newsletter');

            setTimeout(() => {
                button.textContent = originalText;
                button.disabled = false;
            }, 2000);
        }, 800);
    });
}

function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

function showValidationError(message) {
    const errorDiv = document.createElement('div');
    errorDiv.setAttribute('role', 'alert');
    errorDiv.style.cssText = `
        background-color: #f44336;
        color: white;
        padding: 1rem;
        border-radius: 0.5rem;
        margin-bottom: 1rem;
        position: fixed;
        top: 1rem;
