/* Reset and Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary-color: #1a1a1a;
    --secondary-color: #ffffff;
    --accent-color: #d4a574;
    --light-gray: #f5f5f5;
    --medium-gray: #e8e8e8;
    --dark-gray: #666666;
    --border-color: #e0e0e0;
    --success-color: #4caf50;
    --error-color: #f44336;

    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;

    --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --font-size-base: 1rem;
    --font-size-lg: 1.125rem;
    --font-size-xl: 1.25rem;
    --font-size-2xl: 1.5rem;
    --font-size-3xl: 2rem;
    --font-size-4xl: 2.5rem;

    --transition: all 0.3s ease;
    --border-radius: 0.5rem;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-family);
    font-size: var(--font-size-base);
    line-height: 1.6;
    color: var(--primary-color);
    background-color: var(--secondary-color);
}

/* Accessibility */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--primary-color);
    padding: var(--spacing-md) var(--spacing-lg);
    text-decoration: none;
    z-index: 100;
    font-weight: 600;
}

.skip-link:focus {
    top: 0;
}

/* Focus Styles */
:focus-visible {
    outline: 3px solid var(--accent-color);
    outline-offset: 2px;
}

button:focus-visible,
a:focus-visible {
    outline: 3px solid var(--accent-color);
    outline-offset: 2px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    line-height: 1.2;
    font-weight: 600;
}

h1 {
    font-size: var(--font-size-4xl);
}

h2 {
    font-size: var(--font-size-3xl);
    margin-bottom: var(--spacing-md);
}

h3 {
    font-size: var(--font-size-xl);
    margin-bottom: var(--spacing-sm);
}

p {
    margin-bottom: var(--spacing-md);
}

/* Layout Utilities */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

/* Header */
.header {
    background-color: var(--secondary-color);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo-section {
    flex: 0 0 auto;
}

.logo {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    margin: 0;
    letter-spacing: -0.5px;
}

/* Navigation */
.primary-nav {
    flex: 1;
    margin: 0 var(--spacing-2xl);
}

.menu-toggle {
    display: none;
    background: none;
    border: none;
    padding: var(--spacing-sm);
    cursor: pointer;
    font-size: var(--font-size-lg);
}

.hamburger {
    display: block;
    width: 24px;
    height: 16px;
    position: relative;
}

.hamburger::before,
.hamburger::after {
    content: '';
    position: absolute;
    width: 100%;
    height: 2px;
    background-color: var(--primary-color);
    left: 0;
    transition: var(--transition);
}

.hamburger::before {
    top: 0;
}

.hamburger::after {
    bottom: 0;
}

.nav-menu {
    list-style: none;
    display: flex;
    gap: var(--spacing-xl);
}

.nav-link {
    text-decoration: none;
    color: var(--primary-color);
    font-weight: 500;
    transition: var(--transition);
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--accent-color);
    transition: var(--transition);
}

.nav-link:hover::after {
    width: 100%;
}

/* Header Actions */
.header-actions {
    display: flex;
    gap: var(--spacing-lg);
    align-items: center;
}

.search-btn,
.cart-btn {
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--spacing-sm);
    color: var(--primary-color);
    display: flex;
    align-items: center;
    justify-content: center;
    transition: var(--transition);
}

.search-btn:hover,
.cart-btn:hover {
    color: var(--accent-color);
}

.cart-btn {
    position: relative;
}

.cart-count {
    position: absolute;
    top: 0;
    right: 0;
    background-color: var(--accent-color);
    color: var(--primary-color);
    font-size: 0.7rem;
    font-weight: 700;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, var(--primary-color) 0%, #2a2a2a 100%);
    color: var(--secondary-color);
    padding: 6rem var(--spacing-lg);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content h2 {
    font-size: var(--font-size-4xl);
    color: var(--secondary-color);
    margin-bottom: var(--spacing-md);
}

.hero-content p {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-2xl);
    opacity: 0.9;
}

/* Buttons */
.cta-button,
.add-to-cart-btn,
.deal-btn,
.subscribe-btn {
    background-color: var(--accent-color);
    color: var(--primary-color);
    border: 2px solid var(--accent-color);
    padding: var(--spacing-sm) var(--spacing-lg);
    font-size: var(--font-size-base);
    font-weight: 600;
    border-radius: var(--border-radius);
    cursor: pointer;
    transition: var(--transition);
}

.cta-button:hover,
.add-to-cart-btn:hover,
.deal-btn:hover,
.subscribe-btn:hover {
    background-color: var(--primary-color);
    color: var(--secondary-color);
}

.cta-button:active,
.add-to-cart-btn:active,
.deal-btn:active,
.subscribe-btn:active {
    transform: scale(0.98);
}

/* Sections */
.featured-section,
.deals-section,
.editorial-section {
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.featured-section {
    background-color: var(--secondary-color);
}

.deals-section {
    background-color: var(--light-gray);
}

.editorial-section {
    background-color: var(--secondary-color);
}

.section-subtitle {
    color: var(--dark-gray);
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-2xl);
}

/* Products Grid */
.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: var(--spacing-2xl);
    margin-bottom: var(--spacing-2xl);
}

.product-card {
    background-color: var(--secondary-color);
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: var(--transition);
}

.product-card:hover {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
    transform: translateY(-4px);
}

.product-image-wrapper {
    position: relative;
    overflow: hidden;
    background-color: var(--light-gray);
    aspect-ratio: 3 / 4;
}

.product-image-wrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.product-card:hover .product-image-wrapper img {
    transform: scale(1.05);
}

.product-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--accent-color);
    color: var(--primary-color);
    padding: var(--spacing-xs) var(--spacing-md);
    font-size: 0.85rem;
    font-weight: 600;
    border-radius: var(--border-radius);
}

.product-badge.sale {
    background-color: var(--error-color);
    color: var(--secondary-color);
}

.product-info {
    padding: var(--spacing-lg);
}

.product-description {
    font-size: 0.9rem;
    color: var(--dark-gray);
    margin-bottom: var(--spacing-sm);
}

.product-rating {
    font-size: 0.9rem;
    margin-bottom: var(--spacing-md);
    color: var(--dark-gray);
}

.product-price-section {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.price {
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--primary-color);
}

.add-to-cart-btn {
    width: auto;
    padding: var(--spacing-sm) var(--spacing-lg);
    font-size: 0.9rem;
}

/* Deals Section */
.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-2xl);
}

.deal-card {
    background-color: var(--secondary-color);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: var(--transition);
}

.deal-card:hover {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
}

.deal-badge {
    position: absolute;
    top: var(--spacing-lg);
    left: var(--spacing-lg);
    background-color: var(--error-color);
    color: var(--secondary-color);
    padding: var(--spacing-sm) var(--spacing-lg);
    font-weight: 700;
    border-radius: var(--border-radius);
    z-index: 10;
}

.deal-card img {
    width: 100%;
    height: 200px;
    object-fit: cover;
    display: block;
    position: relative;
}

.deal-info {
    padding: var(--spacing-lg);
}

.deal-info h3 {
    margin-bottom: var(--spacing-sm);
}

.deal-info p {
    color: var(--dark-gray);
    margin-bottom: var(--spacing-lg);
    font-size: 0.95rem;
}

.deal-btn {
    width: 100%;
    padding: var(--spacing-md) var(--spacing-lg);
}

/* Editorial Grid */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-2xl);
}

.editorial-card {
    background-color: var(--secondary-color);
    border: 1px solid var(--border-color);
    border-radius: var(--border-radius);
    overflow: hidden;
    transition: var(--transition);
}

.editorial-card:hover {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.1);
    transform: translateY(-4px);
}

.editorial-image {
    overflow: hidden;
    height: 240px;
    background-color: var(--light-gray);
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.editorial-card:hover .editorial-image img {
    transform: scale(1.05);
}

.editorial-content {
    padding: var(--spacing-lg);
}

.article-date {
    display: block;
    font-size: 0.9rem;
    color: var(--dark-gray);
    margin-bottom: var(--spacing-sm);
}

.editorial-content h3 {
    margin-bottom: var(--spacing-md);
}

.editorial-content p {
    color: var(--dark-gray);
    margin-bottom: var(--spacing-lg);
    font-size: 0.95rem;
}

.read-more {
    display: inline-block;
    color: var(--accent-color);
    text-decoration: none;
    font-weight: 600;
    transition: var(--transition);
}

.read-more:hover {
    color: var(--primary-color);
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--primary-color) 0%, #2a2a2a 100%);
    color: var(--secondary-color);
    padding: var(--spacing-2xl) var(--spacing-lg);
}

.newsletter-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--spacing-2xl);
}

.newsletter-content h2 {
    color: var(--secondary-color);
}

.newsletter-content p {
    color: rgba(255, 255, 255, 0.9);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-md);
    min-width: 350px;
}

.form-group {
    flex: 1;
}

.newsletter-form input {
    width: 100%;
    padding: var(--spacing-md);
    border: 2px solid var(--border-color);
    border-radius: var(--border-radius);
    font-size: var(--font-size-base);
    background-color: var(--secondary-color);
    color: var(--primary-color);
    font-family: var(--font-family);
}

.newsletter-form input::placeholder {
    color: var(--medium-gray);
}

.newsletter-form input:focus {
    border-color: var(--accent-color);
}

.subscribe-btn {
    white-space: nowrap;
}

/* Footer */
.footer {
    background-color: var(--primary-color);
    color: var(--secondary-color);
    padding: var(--spacing-2xl) var(--spacing-lg) var(--spacing-lg);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-2xl);
    margin-bottom: var(--spacing-2xl);
}

.footer-column h3 {
    color: var(--secondary-color);
    margin-bottom: var(--spacing-lg);
}

.footer-column ul {
    list-style: none;
}

.footer-column a {
    display: block;
    color: rgba(255, 255, 255, 0.8);
    text-decoration: none;
    margin-bottom: var(--spacing-md);
    transition: var(--transition);
}

.footer-column a:hover {
    color: var(--accent-color);
}

.footer-bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    padding-top: var(--spacing-lg);
    text-align: center;
    font-size: 0.9rem;
    color: rgba(255, 255, 255, 0.6);
}

/* Responsive Design */
@media (max-width: 768px) {
    :root {
        --font-size-base: 0.95rem;
        --font-size-2xl: 1.25rem;
        --font-size-3xl: 1.75rem;
        --font-size-4xl: 2rem;
    }

    .header-container {
        flex-wrap: wrap;
        gap: var(--spacing-md);
    }

    .menu-toggle {
        display: block;
    }

    .primary-nav {
        margin: 0;
        flex-basis: 100%;
        order: 3;
    }

    .nav-menu {
        flex-direction: column;
        gap: var(--spacing-md);
        padding: var(--spacing-lg) 0;
        max-height: 0;
        overflow: hidden;
        transition: var(--transition);
    }

    .nav-menu.active {
        max-height: 500px;
    }

    .hero {
        padding: 3rem var(--spacing-lg);
        min-height: 300px;
    }

    .hero-content h2 {
        font-size: var(--font-size-2xl);
    }

    .hero-content p {
        font-size: var(--font-size-base);
    }

    .featured-section,
    .deals-section,
    .editorial-section {
        padding: var(--spacing-xl) var(--spacing-lg);
    }

    .products-grid {
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
        gap: var(--spacing-lg);
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-container {
        flex-direction: column;
        align-items: stretch;
    }

    .newsletter-form {
        flex-direction: column;
        min-width: 100%;
    }

    .newsletter-form input {
        width: 100%;
    }

    .footer-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 480px) {
    .container {
        padding: 0 var(--spacing-md);
    }

    .header-container {
        padding: var(--spacing-md);
    }

    :root {
        --font-size-base: 0.9rem;
        --font-size-2xl: 1.1rem;
        --font-size-3xl: 1.4rem;
        --spacing-xl: 1.25rem;
        --spacing-2xl: 1.5rem;
    }

    .hero-content h2 {
        font-size: 1.5rem;
    }

    .products-grid {
        grid-template-columns: 1fr;
    }

    .deals-grid {
        grid-template-columns: 1fr;
    }

    .editorial-grid {
        grid-template-columns: 1fr;
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }

    .newsletter-form input::placeholder {
        font-size: 0.9rem;
    }
}

/* Forced Colors Mode Support */
@media (prefers-forced-colors: active) {
    .product-card,
    .deal-card,
    .editorial-card {
        border: 2px solid currentColor;
    }

    .cta-button,
    .add-to-cart-btn,
    .deal-btn,
    .subscribe-btn {
        forced-color-adjust: none;
        border: 2px solid currentColor;
    }

    .skip-link:focus {
        outline: 3px solid currentColor;
    }
}

/* Reduced Motion Support */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

/* Print Styles */
@media print {
    .header,
    .newsletter-section,
    .footer {
        display: none;
    }

    .hero {
        background: none;
        color: var(--primary-color);
    }

    a {
        text-decoration: underline;
    }
}

// Cart state
const cartState = {
    items: [],
    count: 0
};

// Mobile menu toggle
const menuToggle = document.querySelector('.menu-toggle');
const navMenu = document.querySelector('#nav-menu');

menuToggle.addEventListener('click', () => {
    const isExpanded = menuToggle.getAttribute('aria-expanded') === 'true';
    menuToggle.setAttribute('aria-expanded', !isExpanded);
    navMenu.classList.toggle('active');
});

// Close menu when clicking on a nav link
const navLinks = document.querySelectorAll('.nav-link');
navLinks.forEach(link => {
    link.addEventListener('click', () => {
        menuToggle.setAttribute('aria-expanded', 'false');
        navMenu.classList.remove('active');
    });
});

// Add to cart functionality
const addToCartButtons = document.querySelectorAll('.add-to-cart-btn');
const cartCount = document.querySelector('.cart-count');

addToCartButtons.forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();

        const productCard = button.closest('.product-card');
        const productName = productCard.querySelector('h3').textContent;
        const price = productCard.querySelector('.price').textContent;

        // Add item to cart
        cartState.items.push({
            name: productName,
            price: price
        });
        cartState.count++;

        // Update cart UI
        updateCart();

        // Show feedback
        showCartFeedback(button);
    });
});

function updateCart() {
    cartCount.textContent = cartState.count;
    cartCount.setAttribute('aria-label', `${cartState.count} items in cart`);
}

function showCartFeedback(button) {
    const originalText = button.textContent;
    button.textContent = 'Added!';
    button.disabled = true;

    setTimeout(() => {
        button.textContent = originalText;
        button.disabled = false;
    }, 1500);
}

// Deal buttons
const dealButtons = document.querySelectorAll('.deal-btn');
dealButtons.forEach(button => {
    button.addEventListener('click', (e) => {
        e.preventDefault();
        const dealCard = button.closest('.deal-card');
        const dealTitle = dealCard.querySelector('h3').textContent;

        // Announce to screen readers
        announceAction(`Viewing ${dealTitle} collection`);
    });
});

// Newsletter form
const newsletterForm = document.querySelector('.newsletter-form');
const emailInput = document.querySelector('#email');

if (newsletterForm) {
    newsletterForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const email = emailInput.value;

        // Basic email validation
        if (!isValidEmail(email)) {
            showValidationError('Please enter a valid email address');
            return;
        }

        // Simulate submission
        const button = newsletterForm.querySelector('button');
        const originalText = button.textContent;
        button.disabled = true;
        button.textContent = 'Subscribing...';

        setTimeout(() => {
            button.textContent = 'Subscribed!';
            emailInput.value = '';
            announceAction('Successfully subscribed to our newsletter');

            setTimeout(() => {
                button.textContent = originalText;
                button.disabled = false;
            }, 2000);
        }, 800);
    });
}

function isValidEmail(email) {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

function showValidationError(message) {
