* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary-color: #1a1a1a;
    --secondary-color: #ffffff;
    --accent-color: #d4a574;
    --light-gray: #f5f5f5;
    --medium-gray: #e8e8e8;
    --dark-gray: #666666;
    --border-color: #e0e0e0;
    --success-color: #4caf50;
    --error-color: #f44336;

    --spacing-xs: 0.25rem;
    --spacing-sm: 0.5rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;

    --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --font-size-base: 1rem;
    --font-size-lg: 1.125rem;
    --font-size-xl: 1.25rem;
    --font-size-2xl: 1.5rem;
    --font-size-3xl: 2rem;
    --font-size-4xl: 2.5rem;

    --transition: all 0.3s ease;
    --border-radius: 0.5rem;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-family);
    font-size: var(--font-size-base);
    line-height: 1.6;
    color: var(--primary-color);
    background-color: var(--secondary-color);
}

/* Accessibility */
.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: var(--primary-color);
    padding: var(--spacing-md) var(--spacing-lg);
    text-decoration: none;
    z-index: 100;
    font-weight: 600;
}

.skip-link:focus {
    top: 0;
}

/* Focus Styles */
:focus-visible {
    outline: 3px solid var(--accent-color);
    outline-offset: 2px;
}

button:focus-visible,
a:focus-visible {
    outline: 3px solid var(--accent-color);
    outline-offset: 2px;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
    line-height: 1.2;
    font-weight: 600;
}

h1 {
    font-size: var(--font-size-4xl);
}

h2 {
    font-size: var(--font-size-3xl);
    margin-bottom: var(--spacing-md);
}

h3 {
    font-size: var(--font-size-xl);
    margin-bottom: var(--spacing-sm);
}

p {
    margin-bottom: var(--spacing-md);
}

/* Layout Utilities */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-lg);
}

/* Header */
.header {
    background-color: var(--secondary-color);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 50;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo-section {
    flex: 0 0 auto;
}

.logo {
    font-size: var(--font-size-2xl);
    font-weight: 700;
    margin: 0;
    letter-spacing: -0.5px;
}

/* Navigation */
.primary-nav {
    flex: 1;
    margin: 0 var(--spacing-2xl);
}

.menu-toggle {
    display: none;
    background: none;
    border: none;
    padding: var(--spacing-sm);
    cursor: pointer;
    font-size: var(--font-size-lg);
}

.hamburger {
    display: block;
    width: 24px;
    height: 16px;
    position: relative;
}

.hamburger::before,
.hamburger::after {
    content: '';
    position: absolute;
    width: 100%;
    height: 2px;
    background-color: var(--primary-color);
    left: 0;
    transition: var(--transition);
}

.hamburger::before {
    top: 0;
}

.hamburger::after {
    bottom: 0;
}

.nav-menu {
    list-style: none;
    display: flex;
    gap: var(--spacing-xl);
}

.nav-link {
    text-decoration: none;
