    position: relative;
}

.deal-info {
    padding: var(--spacing-lg);
}

.deal-info h3 {
    margin-bottom: var(--spacing-sm);
}

.deal-info p {
    color: var(--dark-gray);
    margin-bottom: var(--spacing-lg);
    font-size: 0.95rem;
}

.deal-btn {
    width: 100%;
    padding: var(--spacing-md) var(--spacing-lg);
}

/* Editorial Grid */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-2xl);
}

.editorial-card {
