  console.log('\n=== ACCESSIBILITY TEST RESULTS ===\n');

  if (wcagViolations.length === 0 && bpViolations.length === 0) {
    console.log('✓ All tests passed! No violations found.');
    return { wcag: [], bp: [] };
  }

  if (wcagViolations.length > 0) {
    console.log('WCAG 2.2 Violations found:');
    wcagViolations.forEach(v => {
      console.log(`\n  ${v.id} (${v.impact})`);
      console.log(`  Description: ${v.description}`);
      console.log(`  Help: ${v.help}`);
      console.log(`  Targets:`);
      v.nodes.forEach(n => {
        console.log(`    - ${n.target.join(' > ')}`);
      });
    });
  }

  if (bpViolations.length > 0) {
    console.log('\nBest Practice warnings:');
    bpViolations.forEach(v => {
      console.log(`\n  ${v.id}`);
      console.log(`  Description: ${v.description}`);
      v.nodes.forEach(n => {
        console.log(`    - ${n.target.join(' > ')}`);
      });
    });
  }

  return {
    wcag: wcagViolations.map(v => ({
      id: v.id,
      impact: v.impact,
      targets: v.nodes.map(n => n.target.join(' > '))
    })),
